package com.pratik.imagetap;
import android.graphics.*;import android.view.*;import android.widget.*;import android.content.Context;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE)
public class UiRenderTest {
    private MainActivity activity;
    @Before public void start(){Context context=RuntimeEnvironment.getApplication();context.getSharedPreferences("config",0).edit().clear().putBoolean("reduceMotion",true).commit();activity=Robolectric.buildActivity(MainActivity.class).setup().get();}
    @After public void stop(){activity.finish();}
    private static void save(View view,String name,int w,int h)throws Exception{view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));view.layout(0,0,w,h);Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);view.draw(canvas);File folder=new File("build/ui-previews");folder.mkdirs();try(FileOutputStream stream=new FileOutputStream(new File(folder,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
    private View root(){return ((android.view.ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);}
    private void tab(int n)throws Exception{Field field=MainActivity.class.getDeclaredField("tab");field.setAccessible(true);field.set(activity,n);Method method=MainActivity.class.getDeclaredMethod("render");method.setAccessible(true);method.invoke(activity);}
    @Test public void renderTabsAndCheckActions()throws Exception{for(int n=0;n<4;n++){tab(n);save(root(),"tab-"+n,824,1656);assertNotNull(find(root(),"Home"));assertNotNull(find(root(),"Actions"));assertNotNull(find(root(),"Regions"));assertNotNull(find(root(),"Settings"));}tab(0);assertNotNull(find(root(),"Start session"));Switch actual=(Switch)find(root(),"Allow actions");assertFalse(actual.isChecked());actual.performClick();assertTrue(activity.getSharedPreferences("config",0).getBoolean("tap",false));assertNull(find(root(),"Smart"));assertFalse(activity.getSharedPreferences("config",0).getBoolean("smart",true));}
    @Test public void renderRegionEditor()throws Exception{Bitmap bitmap=Bitmap.createBitmap(824,1656,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLACK);RegionEditor editor=new RegionEditor(activity,bitmap,Arrays.asList(new RegionRules.Region(.08f,.15f,.92f,.35f,85),new RegionRules.Region(.08f,.5f,.92f,.65f,100,true)),result->{});Ui.polish(editor);save(editor,"regions",824,1656);bitmap.recycle();}
    @Test public void renderFocusAndPulse()throws Exception{FocusOverlay overlay=new FocusOverlay(activity);overlay.preferences(true,true);overlay.candidate(new Rect(540,260,730,340),"Candidate · 92");overlay.pulse(635,300);save(overlay,"touch-pulse",824,1656);overlay.preferences(false,true);overlay.candidate(new Rect(540,260,730,340),"Candidate");assertFalse(overlay.isClickable());}
    @Test @Config(sdk=34,qualifiers="w320dp-h600dp-xhdpi") public void compactScreen()throws Exception{tab(0);save(root(),"compact",640,1100);assertNotNull(find(root(),"Start session"));}
    @Test public void pulseFadesAndGuidesCanBeDisabled()throws Exception{FocusOverlay overlay=new FocusOverlay(activity);overlay.preferences(false,false);overlay.layout(0,0,300,300);overlay.pulse(150,150);Bitmap a=Bitmap.createBitmap(300,300,Bitmap.Config.ARGB_8888);overlay.draw(new Canvas(a));assertTrue(Color.alpha(a.getPixel(150,150))>0);android.os.SystemClock.sleep(800);Bitmap b=Bitmap.createBitmap(300,300,Bitmap.Config.ARGB_8888);overlay.draw(new Canvas(b));assertEquals(0,Color.alpha(b.getPixel(150,150)));a.recycle();b.recycle();}
    void openTap()throws Exception{Field f=MainActivity.class.getDeclaredField("actionCollectionOpen");f.setAccessible(true);f.set(activity,true);tab(1);}
    @Test public void renderPopulatedImagesAndCrop()throws Exception{Bitmap image=Bitmap.createBitmap(120,120,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(image);c.drawColor(Ui.SURFACE);Paint paint=new Paint(3);paint.setColor(Ui.GREEN);paint.setStrokeWidth(8);c.drawLine(40,40,80,80,paint);c.drawLine(80,40,40,80,paint);TargetStore.save(activity,image);tab(1);openTap();save(root(),"images-populated",824,1656);assertNotNull(find(root(),"Target 01"));Method crop=MainActivity.class.getDeclaredMethod("showCrop",Bitmap.class);crop.setAccessible(true);crop.invoke(activity,image);save(root(),"crop",824,1656);assertNotNull(find(root(),"Save target"));}
    @Test public void floatingPanelCollapses()throws Exception{org.robolectric.android.controller.ServiceController<TapService> controller=Robolectric.buildService(TapService.class).create();TapService service=controller.get();Field wm=TapService.class.getDeclaredField("wm");wm.setAccessible(true);wm.set(service,service.getSystemService(Context.WINDOW_SERVICE));Field prefs=TapService.class.getDeclaredField("prefs");prefs.setAccessible(true);prefs.set(service,service.getSharedPreferences("config",0));Method show=TapService.class.getDeclaredMethod("showPanel");show.setAccessible(true);show.invoke(service);Field panelField=TapService.class.getDeclaredField("panel");panelField.setAccessible(true);LinearLayout panel=(LinearLayout)panelField.get(service);panel.measure(View.MeasureSpec.makeMeasureSpec(384,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.AT_MOST));save(panel,"floating-expanded",384,panel.getMeasuredHeight());View emblem=((ViewGroup)panel.getChildAt(0)).getChildAt(0);emblem.performClick();assertEquals(View.GONE,panel.getChildAt(1).getVisibility());save(panel,"floating-collapsed",112,112);emblem.performClick();assertEquals(View.VISIBLE,panel.getChildAt(1).getVisibility());service.stopSession("Test complete");controller.destroy();}
    @Test public void pulseSliderUsesSecondsAndClampsToRange()throws Exception{tab(3);SeekBar pulse=firstSeek(root());assertNotNull(pulse);pulse.setProgress(0);assertEquals(100,activity.getSharedPreferences("config",0).getInt("pulseMs",0));assertNotNull(find(root(),"0.1 s"));pulse.setProgress(pulse.getMax());assertEquals(10000,activity.getSharedPreferences("config",0).getInt("pulseMs",0));assertNotNull(find(root(),"10.0 s"));}
    private SeekBar firstSeek(View v){if(v instanceof SeekBar)return (SeekBar)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){SeekBar b=firstSeek(((ViewGroup)v).getChildAt(i));if(b!=null)return b;}return null;}
    private View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View r=find(g.getChildAt(i),text);if(r!=null)return r;}}return null;}
}
